+/**
+ * The supported language an `Accept-Language` header prefers (by q-value,
+ * then order; region tags like `ko-KR` count as `ko`), or `fallback`.
+ */
+export function pickLanguage(header, fallback = "en") {
+  if (typeof header !== "string" || header.trim() === "") return fallback;
+  let best = null;
+  let bestQ = 0;
+  for (const part of header.split(",")) {
+    const [range, ...attrs] = part.trim().split(";");
+    const lang = range.trim().toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(lang)) continue;
+    let q = 1;
+    for (const attr of attrs) {
+      const m = /^\s*q\s*=\s*([0-9.]+)\s*$/i.exec(attr);
+      if (m) q = Number(m[1]);
+    }
+    if (!Number.isFinite(q) || q <= 0 || q > 1) continue;
+    if (q > bestQ) {
+      best = lang;
+      bestQ = q;
+    }
+  }
+  return best ?? fallback;
+}
